window.docContents[123].resolve({"/Planned-constructions/UD-IV/#Core-C______--Planned-constructions--UD-IV":{"contents":"A T& parameter receives the location of the argument instead of a fresh location with a copy.\n\nThe lambda expression [=] evaluates to a closure, a pair of body and environment with read only copies of the basic values and pointers the body uses. It occurs only as initialiser of a std::function, argument of a std::function parameter or return expression.\n\n","context":"Core C++\u0009Planned constructions","header":"5.2. UD IV","id":"/Planned-constructions/UD-IV/#Core-C______--Planned-constructions--UD-IV"},"/Planned-constructions/UD-VI/#Core-C______--Planned-constructions--UD-VI":{"contents":"Overloading of functions and operators by argument type, resolved in , except over std::function parameters. The expression v[i] is the call of operator[], which returns int&.\n\nClass templates only, instantiated in type position, by substitution of the type parameter at instantiation.\n\n","context":"Core C++\u0009Planned constructions","header":"5.4. UD VI","id":"/Planned-constructions/UD-VI/#Core-C______--Planned-constructions--UD-VI"}});